def parse_and_evaluate(input):
    program = parse(input)
    locals = scan_out_declarations(program)
    unassigneds = list_of_unassigned(locals)
    program_env = extend_environment(locals, unassigneds, the_global_environment)
    return evaluate(program, program_env)

parse_and_evaluate("""
def factorial(n):
    return 1 if n == 1 else n * factorial(n - 1)
factorial(5)
""")

parse_and_evaluate("""
def append(xs, ys):
    return ys if is_null(xs) else pair(head(xs), append(tail(xs), ys))
tail(append(list("a", "b"), list("c", "d")))
""")

parse_and_evaluate("""
def map(f, xs):
    return None if is_null(xs) else pair(f(head(xs)), map(f, tail(xs)))
tail(map(lambda x: x + 1, list(1, 2, 3, 4)))
""")
